def thread_partials(x, blocks, threads):
    """Per-thread partial sums of a grid-stride loop over x."""
    stride = blocks * threads
    partials = []
    for b in range(blocks):
        for t in range(threads):
            i = b * threads + t
            s = 0
            while i < len(x):
                s += x[i]
                i += stride
            partials.append(s)
    return partials
